package net.civeira.phylax.feature.observe.observabilityconfig.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.event.ObservabilityConfigEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservabilityConfigEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservabilityConfigEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservabilityConfig entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
